const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),asset=require('./asset-version');
const root=path.resolve(__dirname,'..'),origin='https://outbound-lead-generation.com',route='/guides/linkedin-prospecting-messages/',locales=['en','es','ca','fr'];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const json=v=>JSON.stringify(v).replace(/</g,'\\u003c');const plain=s=>String(s).replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/&#39;|&apos;/g,"'").replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>');
const legacy={'guide-section-1':'l-thread','guide-section-2':'l-route','guide-section-3':'l-paths','guide-section-4':'l-examples','guide-section-4-example-1':'l-examples','guide-section-4-example-2':'l-examples','guide-section-4-example-3':'l-examples','guide-section-4-example-4':'l-examples','guide-section-5':'l-edit','guide-section-6':'l-replies','guide-section-7':'l-handoff','buyer-worksheet':'l-review','worksheet-privacy':'l-review','phrase-review':'l-edit','buyer-decision-guide':'l-service','frequently-asked-questions':'l-faq',sources:'l-sources'};
function tool(p){const u=p.ui;const field=k=>'<label class="j-field'+(k==='message'?' j-wide':'')+'">'+esc(u.fields[k])+(['route','state','evidence'].includes(k)?'<select data-linkedin-field="'+k+'">'+Object.entries(k==='route'?u.routes:k==='state'?u.states:u.evidence).map(([key,value])=>'<option value="'+key+'">'+esc(value)+'</option>').join('')+'</select>':'<textarea '+(k==='message'?'id="phrase-review-text" aria-describedby="phrase-privacy" ':'')+'data-linkedin-field="'+k+'" maxlength="12000" rows="3" autocomplete="off"></textarea>')+'</label>';const button=(a,t)=>'<button class="j-button cursor-interaction" type="button" data-'+a+' disabled>'+esc(t)+'</button>';
return '<details class="j-tool" data-workbook><summary class="cursor-interaction">'+esc(u.summary)+'</summary><div class="j-tool-inner"><p class="j-small" id="phrase-privacy">'+esc(u.privacy)+'</p><p class="j-small">'+esc(u.fallback)+'</p><label class="j-field" data-draft-picker-label hidden>'+esc(u.picker)+'<select data-draft-picker></select></label><div class="j-review-form" aria-describedby="phrase-privacy"><div class="j-fields">'+['route','context','message','state'].map(field).join('')+'</div><div class="j-length"><h4>'+esc(u.counterLabel)+'</h4><p data-length-count role="status" aria-live="polite"></p><p class="j-small">'+esc(u.countNote)+'</p></div><div class="j-row">'+button('phrase-check',u.phraseButton)+'</div><div data-phrase-results hidden><h4>'+esc(u.phraseTitle)+'</h4><p class="j-small">'+esc(u.phraseHelp)+'</p><ul data-phrase-hits></ul></div><details class="j-advanced"><summary class="cursor-interaction">'+esc(u.advanced)+'</summary><div class="j-fields">'+['subject','unknown','owner','evidence'].map(field).join('')+'</div><p class="j-small" data-subject-count></p></details><div class="j-row">'+button('build-review',u.build)+button('new-draft',u.add)+button('remove',u.remove)+button('clear',u.clear)+'</div></div><div data-clear-confirm class="j-confirm" hidden><p>'+esc(u.confirm)+'</p><div class="j-row">'+button('clear-yes',u.yes)+button('clear-no',u.no)+'</div></div><details class="j-advanced"><summary class="cursor-interaction">'+esc(u.example)+'</summary><p class="j-small">'+esc(u.sourcePrivacy)+'</p><label class="j-field">'+esc(u.example)+'<select data-example-select><option value="">'+esc(u.example)+'</option>'+p.samples.map(s=>'<option value="'+s.id+'">'+esc(s.name)+'</option>').join('')+'</select></label><div class="j-row">'+button('use-selected',u.load)+'</div></details><div class="j-report" data-report hidden><h3>'+esc(u.heading)+'</h3><p>'+esc(u.reviewNote)+'</p><div class="j-reply-decision"><h4>'+esc(u.result)+'</h4><p data-decision></p><p data-route-advice></p></div><h4>'+esc(u.draftPreview)+'</h4><p class="j-draft-preview" data-draft-preview></p><dl data-report-notes></dl><div class="j-checks" data-review-checks><h4>'+esc(u.judgmentsTitle)+'</h4>'+u.checks.map(t=>'<label><input type="checkbox"><span>'+esc(t)+'</span></label>').join('')+'</div><div class="j-row">'+button('edit-review',u.edit)+button('print',u.print)+'</div></div><div class="j-row">'+button('export',u.export)+'</div><div data-csv-output hidden><label class="j-field">'+esc(u.csv)+'<textarea data-csv-text readonly rows="7"></textarea></label>'+button('close-csv',u.closeCsv)+'</div><p class="j-status" role="status" aria-live="polite" data-workbook-status></p></div></details>';}

for(const l of locales){const p=JSON.parse(fs.readFileSync(path.join(root,'data/linkedin-article-20261030/'+l+'.json'))),pre=l==='en'?'':'/'+l,url=origin+pre+route,file=path.join(root,(pre+route).slice(1),'index.html');let h=fs.readFileSync(file,'utf8'),main=p.html;const header=h.match(/<header class="site-header journal-site-header">[\s\S]*?<\/header>/)[0];main=main.replace('<div data-linkedin-tool></div>',tool(p));
const sections=[...main.matchAll(/<section class="[^"]*j-section[^"]*" id="([^"]+)" data-section-label="([^"]+)">/g)].map(m=>({id:m[1],label:m[2]}));assert.equal(sections.length,15);const links=sections.map(s=>'<a class="j-section-link cursor-interaction" data-jump="'+s.id+'" href="#'+s.id+'">'+esc(s.label)+'</a>').join('');main=main.replace(/<nav([^>]*data-contents[^>]*)><\/nav>/g,'<nav$1>'+links+'</nav>');for(const [id,target]of Object.entries(legacy)){
 const anchor='<span class="legacy-anchor" id="'+id+'" aria-hidden="true"></span>';
 if(id.startsWith('guide-section-4-example-')){const key=['msp','recruiter','training','design'][Number(id.at(-1))-1];main=main.replace('<div class="j-example" data-case="'+key+'">',anchor+'<div class="j-example" data-case="'+key+'">');}
 else main=main.replace(new RegExp('(<section[^>]*id="'+target+'"[^>]*>)'),'$1'+anchor);
}
const faqs=[...main.matchAll(/<details><summary class="cursor-interaction">([\s\S]*?)<\/summary><p>([\s\S]*?)<\/p><\/details>/g)].map(m=>({question:plain(m[1]),answer:plain(m[2])}));assert.equal(faqs.length,7);const config={locale:l,ui:p.ui,samples:p.samples,legacy};h=h.replace(/<div id="beespoke-linkedin-full"><div class="j-page">(<main[\s\S]*?<\/main>)\s*<\/div><script type="application\/json" data-linkedin-config>[\s\S]*?<\/script><\/div>/,'$1');h=h.replace(/<main\b[^>]*>[\s\S]*?<\/main>/,'<div id="beespoke-linkedin-full"><div class="j-page">'+main+'</div><script type="application/json" data-linkedin-config>'+json(config)+'</script></div>');h=h.replace(/<body\b([^>]*)>/,(m,a)=>a.includes('linkedin-article-page')?m:'<body'+a.replace(/class="([^"]+)"/,'class="$1 linkedin-article-page"')+'>');h=h.replace(/<title>[\s\S]*?<\/title>/,'<title>'+esc(p.title)+'</title>');
for(const [type,name,value]of [['name','description',p.description],['property','og:title',p.title],['property','og:description',p.description],['name','twitter:title',p.title],['name','twitter:description',p.description]])h=h.replace(new RegExp('(<meta '+type+'="'+name+'" content=")[^"]*(")'),(m,a,z)=>a+esc(value)+z);
h=h.replace(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g,(m,raw)=>{const d=JSON.parse(raw);for(const n of d['@graph']||[d]){if(n['@type']==='Article'){n.name=p.h1;n.headline=p.h1;n.description=p.description;n.inLanguage=l;n.datePublished=p.datePublished;n.dateModified=p.dateModified;}if(n['@type']==='FAQPage')n.mainEntity=faqs.map(f=>({'@type':'Question',name:f.question,acceptedAnswer:{'@type':'Answer',text:f.answer}}));if(n['@type']==='BreadcrumbList')n.itemListElement.at(-1).name=p.h1;}return '<script type="application/ld+json">'+json(d)+'</script>';});
h=h.replace(/<link rel="stylesheet" href="\/(?:buyer-guide-worksheet|outbound-message-examples|linkedin-article)\.css[^\"]*">/g,'').replace(/<script src="\/(?:buyer-guide-worksheet|outbound-phrase-review|linkedin-article)\.js[^\"]*" defer><\/script>/g,'');h=h.replace('</head>','<link rel="stylesheet" href="'+asset('/linkedin-article.css')+'"><script src="'+asset('/linkedin-article.js')+'" defer></script></head>');assert.equal(h.match(/<header class="site-header journal-site-header">[\s\S]*?<\/header>/)[0],header);fs.writeFileSync(file,h);
const hub=path.join(root,(pre+'/resources/').slice(1),'index.html');let lib=fs.readFileSync(hub,'utf8');const re=new RegExp('(<a class="journal-resource-link" href="'+pre+route+'"[^>]*><div><h2[^>]*>)[\\s\\S]*?(</h2>)(?:<p>[\\s\\S]*?</p>)?');assert(re.test(lib));lib=lib.replace(re,(m,a,z)=>a+esc(p.h1)+z+'<p>'+esc(p.description)+'</p>');lib=lib.replace(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g,(m,raw)=>{const d=JSON.parse(raw);for(const n of d['@graph']||[d])if(n['@type']==='ItemList'){const item=n.itemListElement.find(x=>x.url===url);assert(item);item.name=p.h1;}return '<script type="application/ld+json">'+json(d)+'</script>';});fs.writeFileSync(hub,lib);
}
let sitemap=fs.readFileSync(path.join(root,'sitemap.xml'),'utf8');for(const l of locales){const u=origin+(l==='en'?'':'/'+l)+route;sitemap=sitemap.replace(new RegExp('(<loc>'+u+'</loc><lastmod>)[^<]+(</lastmod>)'),'$12026-11-02$2');}fs.writeFileSync(path.join(root,'sitemap.xml'),sitemap);console.log('LinkedIn preview candidate: four complete articles, optional private decision reviews, original source boundaries and routes preserved.');
